import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec(torch::Tensor A, torch::Tensor B);
"""

matvec_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>
  #include <cuda_pipeline.h>

using namespace cute;

// C = A * B with A: (M, K) row-major, B: (K, 1)
// Split-K kernel: grid is (M, S); each block reduces a contiguous K-chunk
// with CuTe tensors and vectorized (float4) global loads, then atomically
// accumulates its partial dot product into C[m].
template <int Threads, int Vec>
__global__ __launch_bounds__(Threads)
void matvec_cute_kernel(const float* __restrict__ A,
                        const float* __restrict__ B,
                        float* __restrict__ C,
                        int M, int K, int chunk)
{
  const int m   = blockIdx.x;
  const int tid = threadIdx.x;
  constexpr int TileK = Threads * Vec;
  // K-range owned by this split-K block
  const int k0  = blockIdx.y * chunk;
  const int k1  = min(K, k0 + chunk);
  const int len = k1 - k0;
  if (len <= 0) return;
  const int R    = len / TileK;   // number of full tiles in this chunk
  const int main = R * TileK;     // elements covered by full tiles
  const float* arow = A + (long long)m * (long long)K + k0;
  const float* bptr = B + k0;
  // CuTe views of the chunk of the row of A and of B as (Vec, Threads, R)
  // so that thread `tid` owns `Vec` contiguous elements per tile.
  Tensor gA = make_tensor(make_gmem_ptr(arow),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));
  Tensor gB = make_tensor(make_gmem_ptr(bptr),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));
  Tensor tAgA = gA(_, tid, _);   // (Vec, R) : (1, TileK)
  Tensor tBgB = gB(_, tid, _);   // (Vec, R) : (1, TileK)
  float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
  float acc4 = 0.f, acc5 = 0.f, acc6 = 0.f, acc7 = 0.f;
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  if constexpr (Vec == 8) {
    // Wider thread-level tiling: each thread stages/consumes two 16B
    // vectors per tile (32B/thread/tile). This reduces loop and issue
    // overhead while keeping the same DRAM streaming volume for this
    // memory-bound split-K reduction.
    __shared__ float4 sA[2][Threads][2];
    __shared__ float4 sB[2][Threads][2];
    const float4* ga4 = reinterpret_cast<const float4*>(arow);
    const float4* gb4 = reinterpret_cast<const float4*>(bptr);
    auto stage = [&](int j, int buf) {
      const long long base = (long long)j * (Threads * 2) + (long long)tid * 2;
      __pipeline_memcpy_async(&sA[buf][tid][0], ga4 + base + 0, 16);
      __pipeline_memcpy_async(&sA[buf][tid][1], ga4 + base + 1, 16);
      __pipeline_memcpy_async(&sB[buf][tid][0], gb4 + base + 0, 16);
      __pipeline_memcpy_async(&sB[buf][tid][1], gb4 + base + 1, 16);
      __pipeline_commit();
    };
    if (R > 0) {
      stage(0, 0);
      for (int j = 0; j < R; ++j) {
        const int  cur      = j & 1;
        const int  nxt      = cur ^ 1;
        const bool has_next = (j + 1 < R);
        if (has_next) stage(j + 1, nxt);
        __pipeline_wait_prior(has_next ? 1 : 0);
        __syncthreads();
        float4 a0 = sA[cur][tid][0];
        float4 a1 = sA[cur][tid][1];
        float4 b0 = sB[cur][tid][0];
        float4 b1 = sB[cur][tid][1];
        acc0 += a0.x * b0.x;
        acc1 += a0.y * b0.y;
        acc2 += a0.z * b0.z;
        acc3 += a0.w * b0.w;
        acc4 += a1.x * b1.x;
        acc5 += a1.y * b1.y;
        acc6 += a1.z * b1.z;
        acc7 += a1.w * b1.w;
        __syncthreads();
      }
    }
  } else if constexpr (Vec == 4) {
    __shared__ float4 sA[2][Threads];
    __shared__ float4 sB[2][Threads];
    const float4* ga4 = reinterpret_cast<const float4*>(arow);
    const float4* gb4 = reinterpret_cast<const float4*>(bptr);
    auto stage = [&](int j, int buf) {
      __pipeline_memcpy_async(&sA[buf][tid], ga4 + (long long)j * Threads + tid, 16);
      __pipeline_memcpy_async(&sB[buf][tid], gb4 + (long long)j * Threads + tid, 16);
      __pipeline_commit();
    };
    if (R > 0) {
      stage(0, 0);
      for (int j = 0; j < R; ++j) {
        const int  cur      = j & 1;
        const int  nxt      = cur ^ 1;
        const bool has_next = (j + 1 < R);
        if (has_next) stage(j + 1, nxt);
        __pipeline_wait_prior(has_next ? 1 : 0);
        __syncthreads();
        float4 a = sA[cur][tid];
        float4 b = sB[cur][tid];
        acc0 += a.x * b.x;
        acc1 += a.y * b.y;
        acc2 += a.z * b.z;
        acc3 += a.w * b.w;
        __syncthreads();
      }
    }
  } else {
    for (int j = 0; j < R; ++j) {
      CUTE_UNROLL
      for (int v = 0; v < Vec; ++v) {
        acc0 += tAgA(v, j) * tBgB(v, j);
      }
    }
  }
#else
  if constexpr (Vec == 4) {
    Tensor tAgA4 = recast<float4>(tAgA);   // (R) of float4
    Tensor tBgB4 = recast<float4>(tBgB);   // (R) of float4
    for (int j = 0; j < R; ++j) {
      float4 a = tAgA4(j);
      float4 b = tBgB4(j);
      acc0 += a.x * b.x;
      acc1 += a.y * b.y;
      acc2 += a.z * b.z;
      acc3 += a.w * b.w;
    }
  } else {
    for (int j = 0; j < R; ++j) {
      CUTE_UNROLL
      for (int v = 0; v < Vec; ++v) {
        acc0 += tAgA(v, j) * tBgB(v, j);
      }
    }
  }
#endif
  float acc = (acc0 + acc1) + (acc2 + acc3) + (acc4 + acc5) + (acc6 + acc7);
  // Tail elements if this chunk's length is not a multiple of Threads*Vec
  for (int e = main + tid; e < len; e += Threads) {
    acc += arow[e] * bptr[e];
  }
  // Block-wide reduction (warp shuffles + shared memory)
  __shared__ float smem[Threads / 32];
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    acc += __shfl_down_sync(0xffffffffu, acc, off);
  }
  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) smem[warp] = acc;
  __syncthreads();
  if (warp == 0) {
    constexpr int NW = Threads / 32;
    float v = (lane < NW) ? smem[lane] : 0.f;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      v += __shfl_down_sync(0xffffffffu, v, off);
    }
    if (lane == 0) atomicAdd(&C[m], v);
  }
}
torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be (K, 1)");
  int64_t M = A.size(0);
  int64_t K = A.size(1);
  TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  // Zero-init output: split-K partial results are accumulated via atomicAdd.
  auto C   = torch::zeros({M, 1}, A.options());
  constexpr int Threads = 256;
  const int vec           = (K % 8 == 0) ? 8 : ((K % 4 == 0) ? 4 : 1);
  const int64_t tileK     = (int64_t)Threads * vec;
  // Split-K: partition the very large K reduction across multiple blocks.
  // For Vec=8 keep the same grid parallelism as the previous Vec=4 version
  // by targeting ~32 wide tiles per split (~64K floats per chunk).
  const int64_t targetTiles = (vec == 8) ? 32 : 64;
  int64_t totalTiles = (K + tileK - 1) / tileK;
  int64_t splits     = totalTiles / targetTiles;
  if (splits < 1)  splits = 1;
  if (splits > 64) splits = 64;
  const int64_t chunk       = ((totalTiles + splits - 1) / splits) * tileK;
  const int64_t splitBlocks = (K + chunk - 1) / chunk;
  dim3 block(Threads);
  dim3 grid((unsigned)M, (unsigned)splitBlocks);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (vec == 8) {
    matvec_cute_kernel<Threads, 8><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K, (int)chunk);
  } else if (vec == 4) {
    matvec_cute_kernel<Threads, 4><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K, (int)chunk);
  } else {
    matvec_cute_kernel<Threads, 1><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K, (int)chunk);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matvec launch failed: ",
              cudaGetErrorString(err));
  return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=matvec_cpp_decl,
    cuda_sources=matvec_cuda_src,
    functions=["matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a single
    custom CuTe CUDA kernel (cooperative tiled reduction over K).
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
            B = B.cuda()
            return self._ext.matvec(A, B).cpu()
        if A.dtype != torch.float32:
            return torch.matmul(A, B)
        return self._ext.matvec(A, B)

